	sections = {
		{
			title = "概述",
			text = [=[月光林地是{link:kalimdor}卡利姆多{/link}北部群山中一处隐秘的{link:stranglethorn-vale}山谷{/link}，位于{link:felwood}费伍德森林{/link}与{link:winterspring}冬泉谷{/link}之间。一座静谧的湖泊位于它的中心，四周环绕着银色的草地和古老的树木，湖岸上坐落着{link:nighthaven}永夜港{/link}村。这里是德鲁伊的组织{link:cenarion-circle}塞纳里奥议会{/link}的圣地，也是{link:cenarius}塞纳留斯{/link}之子{link:keeper-remulos}守护者雷姆洛斯{/link}的居所。没有任何军队占据这里。{link:night-elves}暗夜精灵{/link}与{link:tauren}牛头人{/link}以朋友的身份走在它的小径上，它的守卫者不容许境内发生任何暴力。]=],
