		{ id = "rabine-saturna", name = "拉比恩·萨图纳", note = "他的管家" },
		{ id = "tajarri", name = "塔加里", note = "他神殿的守卫者" },
		{ id = "keeper-marandis", name = "守护者玛兰迪斯", note = "寻找他兄弟的遗骸" },
