Translate("zhCN", "rabine-saturna", {
	title = "拉比恩·萨图纳",
	subtitle = "守护者雷姆洛斯的管家",
	found = "永夜港，湖边",
	hint = "到永夜港村寻找守护者的管家。",
	allegiance = "塞纳里奥议会",
	aliases = { "拉比恩" },
	sections = {
		{
			title = "概述",
			text = [=[拉比恩·萨图纳是{link:keeper-remulos}守护者雷姆洛斯{/link}的管家。他代表守护者与来到{link:moonglade}月光林地{/link}的人交谈，并以居住在这片神圣林地中所有人的名义欢迎他们。他耐心而有礼，从不忘记欠下的恩情。档案管理员{link:umber}阿姆伯尔{/link}称他为{link:nighthaven}永夜港{/link}的“管家婆”，而且并不总是带着善意。]=],
		},
		{
			title = "意义",
			text = [=[拉比恩是{link:moonglade}月光林地{/link}伸向世界的手。{link:shadow-council}议会{/link}通过他，请求各民族的陌生人去做它的德鲁伊无法独自完成的事。他相信，守护{link:azeroth}艾泽拉斯{/link}是{link:horde}部落{/link}与{link:alliance}联盟{/link}共同的事业，无论他们有何争执，也无论{link:darnassus}达纳苏斯{/link}的大德鲁伊怎么说。]=],
		},
		{
			title = "事迹",
			text = [=[• 他欢迎{link:thunder-bluff}雷霆崖{/link}和{link:darnassus}达纳苏斯{/link}的使者来到{link:moonglade}林地{/link}，并承诺在那里保护他们。
