			text = [=[{link:auberdine}奥伯丁{/link}曾向{link:moonglade}月光林地{/link}求援，德迪利特把这变成了一堂课。他警告说，这不是练习。{link:cliffspring-falls}峭壁之泉{/link}的水正在毒害{link:darkshore}黑海岸{/link}的鹿，学生必须像普通人一样亲手医治它们，然后才能学会用一句话做到这一点。奥伯丁送回了谢意。德迪利特又加上了自己的警告：{link:darnassus}达纳苏斯{/link}有些人选择对正在这片土地上蔓延的腐化视而不见。]=],
